// Typed handle tables (prevent cross-type mixing).
static const size_t MAX_HANDLES = 1024;

enum HandleTypeId {

    HT_struct_minijail = 0,

    HT_scalar_bytes = 1,

    HT_ptr_i32 = 2,

    HT__COUNT = 3
};

struct HandleTable {
    void* handles[MAX_HANDLES];
    bool valid[MAX_HANDLES];
    uint32_t count;
};

static HandleTable g_tables[HT__COUNT];

static void handles_reset() {
    for (size_t t = 0; t < (size_t)HT__COUNT; t++) {
        g_tables[t].count = 0;
        std::memset(g_tables[t].handles, 0, sizeof(g_tables[t].handles));
        std::memset(g_tables[t].valid, 0, sizeof(g_tables[t].valid));
    }
}

static uint32_t handle_register(uint32_t type_id, void *ptr) {
    if (!ptr) return 0;
    if (type_id >= (uint32_t)HT__COUNT) return 0;
    HandleTable& tab = g_tables[type_id];
    if (tab.count + 1 >= MAX_HANDLES) return 0;
    uint32_t id = ++tab.count;
    tab.handles[id] = ptr;
    tab.valid[id] = true;
    return id;
}

static uint32_t handle_select(uint32_t type_id, uint32_t requested) {
    if (type_id >= (uint32_t)HT__COUNT) return 0;
    HandleTable& tab = g_tables[type_id];
    if (tab.count == 0) return 0;
    if (requested == 0) return tab.count; /* latest */
    uint32_t idx = requested % tab.count;
    if (idx == 0) idx = tab.count;
    return idx;
}

static uint32_t handle_latest_valid(uint32_t type_id) {
    if (type_id >= (uint32_t)HT__COUNT) return 0;
    HandleTable& tab = g_tables[type_id];
    for (uint32_t i = tab.count; i > 0; --i) {
        if (tab.valid[i] && tab.handles[i]) return i;
    }
    return 0;
}

static minijail* ensure_live_minijail() {
    uint32_t idx = handle_latest_valid(HT_struct_minijail);
    if (idx != 0) {
        return (minijail*)g_tables[HT_struct_minijail].handles[idx];
    }
    minijail* jail = minijail_new();
    if (!jail) return nullptr;
    handle_register(HT_struct_minijail, (void*)jail);
    return jail;
}

static void *handle_get(uint32_t type_id, uint32_t requested, bool allow_stale, uint32_t *out_selected) {
    uint32_t idx = handle_select(type_id, requested);
    if (out_selected) *out_selected = idx;
    if (idx == 0) {
        // Prefer valid-state progression for core jail objects.
        if (!allow_stale && type_id == HT_struct_minijail) {
            minijail* seeded = ensure_live_minijail();
            if (seeded && out_selected) {
                *out_selected = g_tables[HT_struct_minijail].count;
            }
            return (void*)seeded;
        }
        return NULL;
    }
    if (type_id >= (uint32_t)HT__COUNT) return NULL;
    HandleTable& tab = g_tables[type_id];
    if (allow_stale || tab.valid[idx]) return tab.handles[idx];
    uint32_t fallback = handle_latest_valid(type_id);
    if (fallback != 0) {
        if (out_selected) *out_selected = fallback;
        return tab.handles[fallback];
    }
    if (type_id == HT_struct_minijail) {
        minijail* seeded = ensure_live_minijail();
        if (seeded && out_selected) {
            *out_selected = g_tables[HT_struct_minijail].count;
        }
        return (void*)seeded;
    }
    return NULL;
}

static void handle_invalidate(uint32_t type_id, uint32_t selected) {
    if (type_id >= (uint32_t)HT__COUNT) return;
    HandleTable& tab = g_tables[type_id];
    if (selected == 0 || selected > tab.count) return;
    void* ptr = tab.handles[selected];
    tab.valid[selected] = false;
    tab.handles[selected] = nullptr;
    if (!ptr) return;
    // Invalidate aliases so stale IDs do not keep resurrecting dead objects.
    for (uint32_t i = 1; i <= tab.count; ++i) {
        if (!tab.valid[i]) continue;
        if (tab.handles[i] == ptr) {
            tab.valid[i] = false;
            tab.handles[i] = nullptr;
        }
    }
}

static void cleanup_live_minijail_handles() {
    HandleTable& tab = g_tables[HT_struct_minijail];
    void* seen[MAX_HANDLES];
    size_t seen_count = 0;
    std::memset(seen, 0, sizeof(seen));

    for (uint32_t i = 1; i <= tab.count; ++i) {
        if (!tab.valid[i]) continue;
        void* ptr = tab.handles[i];
        tab.valid[i] = false;
        tab.handles[i] = nullptr;
        if (!ptr) continue;

        bool duplicate = false;
        for (size_t j = 0; j < seen_count; ++j) {
            if (seen[j] == ptr) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        if (seen_count < MAX_HANDLES) seen[seen_count++] = ptr;
        minijail_destroy((minijail*)ptr);
    }
}

static const char* nonnull_path_arg(const char* path) {
    return (path && path[0]) ? path : "/";
}

